mapper.update:
update batch.job_instance
set instance_status = #{instanceStatus},
    finished_at = coalesce(#{finishedAt}, finished_at),
    version = version + 1,
    updated_at = current_timestamp
where tenant_id = #{tenantId}
  and id = #{id}
  and version = #{expectedVersion}

update batch.job_instance ji
set instance_status = #{instanceStatus},
    finished_at = coalesce(#{finishedAt}, finished_at),
    version = version + 1,
    updated_at = current_timestamp
where ji.tenant_id = #{tenantId}
  and ji.id = #{id}
  and ji.version = #{expectedVersion}
  and ji.instance_status = 'RUNNING'
  and ji.execution_started_at is not null
  and exists (
      select 1 from batch.job_definition jd
      where jd.id = ji.job_definition_id
        and jd.tenant_id = ji.tenant_id
        and  > 0
        and ji.execution_started_at < current_timestamp - ( * interval '1 second')
  )
  and exists (
      select 1 from batch.job_task task
      where task.tenant_id = #{tenantId}
        and task.job_instance_id = #{id}
        and task.task_status = 'RUNNING'
  )

update batch.job_instance
set instance_status = #{instanceStatus},
    version = version + 1,
    updated_at = current_timestamp
where tenant_id = #{tenantId}
  and id = #{id}
  and version = #{expectedVersion}

