update batch.pipeline_step_run step set step_status = #{interruptedStepStatus}, error_code = 'PIPELINE_ATTEMPT_INTERRUPTED', error_message = 'Step attempt did not finish before its Job reached a terminal state', error_key = 'error.pipeline.attempt_interrupted', error_args = null, finished_at = current_timestamp, duration_ms = greatest(0, extract(epoch from (current_timestamp - coalesce(step.started_at, current_timestamp))) * 1000)::bigint from batch.pipeline_instance pipeline join batch.job_instance job on job.tenant_id = pipeline.tenant_id and job.id = pipeline.related_job_instance_id where step.pipeline_instance_id = pipeline.id and pipeline.tenant_id = #{tenantId} and job.id = #{id} and job.instance_status = #{terminalInstanceStatus} and job.instance_status in
#{status}
and step.step_status in ('RUNNING', 'RETRYING')
